CREATE TABLE TEST_AS_ORDERS (
     id NUMBER,
     name VARCHAR2(100),
     status VARCHAR2(20),
     value NUMBER
   ) TABLESPACE TEST002;
   INSERT INTO TEST_AS_ORDERS SELECT ROWNUM, RPAD('NAME', 100, 'X'),
     CASE MOD(ROWNUM, 3) WHEN 0 THEN 'ACTIVE' WHEN 1 THEN 'INACTIVE' ELSE 'PENDING' END, ROWNUM
   FROM (SELECT ROWNUM FROM dual CONNECT BY LEVEL <= 50000);
   COMMIT;
CREATE TABLE REPORT_SECTIONS_AS_001 (section_name VARCHAR2(100), status VARCHAR2(20)) TABLESPACE TEST002;
INSERT INTO REPORT_SECTIONS_AS_001 SELECT 'section_'||LEVEL, 'complete' FROM dual CONNECT BY LEVEL <= 5;
COMMIT;

